 	if dataEngine != nil {
 		var ok bool
 		engine, ok = dataEngine.(*dataengine.DataEngine)
 		if !ok {
 			return nil, fmt.Errorf("invalid data engine type %T", dataEngine)
 		}
 	}

 	return network.NewGoReverseProxy(cfg, frontendURL, backendURL, engine)
 }

