 							embeddingProvider,
 							graphEngine,
 							faissManager,
 							nil,
 							logger,
 						)

 						searchEngine := icme.NewHybridSearchEngine(
 							faissManager,
 							graphEngine,
 							intentRegistry,
 							logger,
 						)

