package headless

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"knirvhasher/internal/cli/controller"
)

// TestNewServer tests server creation
func TestNewServer(t *testing.T) {
	s := NewServer(8089)
	if s == nil {
		t.Fatal("NewServer returned nil")
	}
	if s.port != 8089 {
		t.Errorf("expected port 8089, got %d", s.port)
	}
	if s.controller == nil {
		t.Error("controller is nil")
	}
}

// TestHealthEndpoint tests the health check endpoint
func TestHealthEndpoint(t *testing.T) {
	s := NewServer(8090)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodGet, "/api/v1/health", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Errorf("expected status 200, got %d", w.Code)
	}

	expected := "OK"
	if w.Body.String() != expected {
		t.Errorf("expected body %q, got %q", expected, w.Body.String())
	}
}

// TestGetStatus tests the status endpoint
func TestGetStatus(t *testing.T) {
	s := NewServer(8091)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodGet, "/api/v1/status", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Errorf("expected status 200, got %d", w.Code)
	}

	var statusResp controller.StatusResponse
	if err := json.NewDecoder(w.Body).Decode(&statusResp); err != nil {
		t.Fatalf("failed to decode response: %v", err)
	}

	if statusResp.Status != "ok" {
		t.Errorf("expected status 'ok', got %q", statusResp.Status)
	}
}

// TestStartDriver tests the driver start endpoint
func TestStartDriver(t *testing.T) {
	s := NewServer(8092)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodPost, "/api/v1/driver/start", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// The driver start might fail in test environment, but endpoint should respond
	if w.Code != http.StatusOK && w.Code != http.StatusInternalServerError {
		t.Errorf("unexpected status code: %d", w.Code)
	}
}

// TestStopDriver tests the driver stop endpoint
func TestStopDriver(t *testing.T) {
	s := NewServer(8093)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodPost, "/api/v1/driver/stop", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// Status should be OK even if no driver was running
	if w.Code != http.StatusOK {
		t.Errorf("expected status 200, got %d", w.Code)
	}
}

// TestRunPipeline tests the pipeline run endpoint
func TestRunPipeline(t *testing.T) {
	s := NewServer(8094)
	defer s.Stop()

	payload := map[string]string{"type": "goat"}
	body, _ := json.Marshal(payload)

	req := httptest.NewRequest(http.MethodPost, "/api/v1/pipeline/run", bytes.NewBuffer(body))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// Pipeline might fail in test environment, but endpoint should respond
	if w.Code != http.StatusOK && w.Code != http.StatusInternalServerError {
		t.Errorf("unexpected status code: %d", w.Code)
	}
}

// TestGetPipelineStatus tests the pipeline status endpoint
func TestGetPipelineStatus(t *testing.T) {
	s := NewServer(8095)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodGet, "/api/v1/pipeline/status", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Errorf("expected status 200, got %d", w.Code)
	}

	var statusResp controller.PipelineStatusResponse
	if err := json.NewDecoder(w.Body).Decode(&statusResp); err != nil {
		t.Fatalf("failed to decode response: %v", err)
	}

	// Check that response has required fields
	if statusResp.Running && statusResp.Complete {
		t.Error("pipeline cannot be both running and complete")
	}
}

// TestDiscoverASIC tests the ASIC discovery endpoint
func TestDiscoverASIC(t *testing.T) {
	s := NewServer(8096)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodPost, "/api/v1/asic/discover", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// Discovery might fail in test environment
	if w.Code != http.StatusOK && w.Code != http.StatusInternalServerError {
		t.Errorf("unexpected status code: %d", w.Code)
	}

	if w.Code == http.StatusOK {
		var discoverResp controller.DiscoveryResponse
		if err := json.NewDecoder(w.Body).Decode(&discoverResp); err != nil {
			t.Fatalf("failed to decode response: %v", err)
		}
	}
}

// TestProbeASIC tests the ASIC probe endpoint
func TestProbeASIC(t *testing.T) {
	s := NewServer(8097)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodPost, "/api/v1/asic/probe", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// Probe might fail without discovery first
	if w.Code != http.StatusOK && w.Code != http.StatusInternalServerError {
		t.Errorf("unexpected status code: %d", w.Code)
	}
}

// TestDetectProtocol tests the protocol detection endpoint
func TestDetectProtocol(t *testing.T) {
	s := NewServer(8098)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodPost, "/api/v1/asic/protocol", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// Protocol detection might fail without probe first
	if w.Code != http.StatusOK && w.Code != http.StatusInternalServerError {
		t.Errorf("unexpected status code: %d", w.Code)
	}
}

// TestPipelineLogsSSE tests the SSE pipeline logs endpoint
func TestPipelineLogsSSE(t *testing.T) {
	s := NewServer(8099)
	defer s.Stop()

	// Start pipeline in background
	go func() {
		payload := map[string]string{"type": "demo"}
		body, _ := json.Marshal(payload)
		req := httptest.NewRequest(http.MethodPost, "/api/v1/pipeline/run", bytes.NewBuffer(body))
		req.Header.Set("Content-Type", "application/json")
		w := httptest.NewRecorder()
		s.mux.ServeHTTP(w, req)
	}()

	// Give it a moment to start
	time.Sleep(100 * time.Millisecond)

	// Check logs endpoint
	req := httptest.NewRequest(http.MethodGet, "/api/v1/pipeline/logs", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// SSE endpoint should at least accept the request
	// In a real test, we'd check the SSE stream
}

// TestShutdownEndpoint tests the shutdown endpoint
func TestShutdownEndpoint(t *testing.T) {
	s := NewServer(8100)

	req := httptest.NewRequest(http.MethodPost, "/api/v1/shutdown", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// Shutdown should return accepted
	if w.Code != http.StatusAccepted {
		t.Errorf("expected status 202, got %d", w.Code)
	}

	s.Stop()
}

// TestManageRules tests the rules management endpoint
func TestManageRules(t *testing.T) {
	s := NewServer(8101)
	defer s.Stop()

	// Test GET (list rules)
	req := httptest.NewRequest(http.MethodGet, "/api/v1/rules", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Errorf("expected status 200, got %d", w.Code)
	}

	// Test POST (add rule)
	rulePayload := map[string]interface{}{
		"action":    "add",
		"domain":    "temperature",
		"type":      "constraint",
		"conclusion": "Valid range: -40 to 85",
	}
	body, _ := json.Marshal(rulePayload)
	req = httptest.NewRequest(http.MethodPost, "/api/v1/rules", bytes.NewBuffer(body))
	req.Header.Set("Content-Type", "application/json")
	w = httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// Adding rule might succeed or fail depending on environment
	if w.Code != http.StatusOK && w.Code != http.StatusInternalServerError {
		t.Errorf("unexpected status code: %d", w.Code)
	}
}

// TestChatEndpoint tests the chat endpoint
func TestChatEndpoint(t *testing.T) {
	s := NewServer(8102)
	defer s.Stop()

	chatPayload := map[string]string{"message": "Hello, ASIC!"}
	body, _ := json.Marshal(chatPayload)

	req := httptest.NewRequest(http.MethodPost, "/api/v1/chat", bytes.NewBuffer(body))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// Chat might fail without proper setup, but endpoint should respond
	if w.Code != http.StatusOK && w.Code != http.StatusInternalServerError {
		t.Errorf("unexpected status code: %d", w.Code)
	}
}

// TestServerStartStop tests the server lifecycle
func TestServerStartStop(t *testing.T) {
	s := NewServer(8103)

	// Start server
	go func() {
		if err := s.Start(); err != nil {
			t.Errorf("failed to start server: %v", err)
		}
	}()

	// Give it a moment to start
	time.Sleep(100 * time.Millisecond)

	// Test that server is running
	resp, err := http.Get("http://localhost:8103/api/v1/health")
	if err != nil {
		t.Fatalf("failed to connect to server: %v", err)
	}
	if resp.StatusCode != http.StatusOK {
		t.Errorf("expected status 200, got %d", resp.StatusCode)
	}
	resp.Body.Close()

	// Stop server
	s.Stop()

	// Give it a moment to stop
	time.Sleep(100 * time.Millisecond)

	// Server should no longer respond
	_, err = http.Get("http://localhost:8103/api/v1/health")
	if err == nil {
		t.Error("expected error after server stop")
	}
}

