package headless

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

// TestNewServer tests server creation
func TestNewServer(t *testing.T) {
	s := NewServer(8089)
	if s == nil {
		t.Fatal("NewServer returned nil")
	}
	if s.port != 8089 {
		t.Errorf("expected port 8089, got %d", s.port)
	}
	if s.controller == nil {
		t.Error("controller is nil")
	}
	s.Stop()
}

// TestHealthEndpoint tests the health check endpoint
func TestHealthEndpoint(t *testing.T) {
	s := NewServer(8090)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodGet, "/api/v1/health", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Errorf("expected status 200, got %d", w.Code)
	}

	// Health returns JSON
	var resp map[string]interface{}
	if err := json.NewDecoder(w.Body).Decode(&resp); err != nil {
		t.Fatalf("failed to decode response: %v", err)
	}

	if resp["status"] != "ok" {
		t.Errorf("expected status 'ok', got %v", resp["status"])
	}
}

// TestGetStatus tests the status endpoint
func TestGetStatus(t *testing.T) {
	s := NewServer(8091)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodGet, "/api/v1/status", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Errorf("expected status 200, got %d", w.Code)
	}

	var statusResp StatusResponse
	if err := json.NewDecoder(w.Body).Decode(&statusResp); err != nil {
		t.Fatalf("failed to decode response: %v", err)
	}
}

// TestMethodNotAllowed tests that endpoints reject wrong methods
func TestMethodNotAllowed(t *testing.T) {
	s := NewServer(8092)
	defer s.Stop()

	// Health only accepts GET
	req := httptest.NewRequest(http.MethodPost, "/api/v1/health", nil)
	w := httptest.NewRecorder()
	s.mux.ServeHTTP(w, req)

	if w.Code != http.StatusMethodNotAllowed {
		t.Errorf("expected status 405, got %d", w.Code)
	}

	// Status only accepts GET
	req = httptest.NewRequest(http.MethodPost, "/api/v1/status", nil)
	w = httptest.NewRecorder()
	s.mux.ServeHTTP(w, req)

	if w.Code != http.StatusMethodNotAllowed {
		t.Errorf("expected status 405, got %d", w.Code)
	}
}

// TestShutdownEndpoint tests the shutdown endpoint
func TestShutdownEndpoint(t *testing.T) {
	s := NewServer(8093)
	defer s.Stop()

	req := httptest.NewRequest(http.MethodPost, "/api/v1/shutdown", nil)
	w := httptest.NewRecorder()

	s.mux.ServeHTTP(w, req)

	// Shutdown should return accepted
	if w.Code != http.StatusAccepted {
		t.Errorf("expected status 202, got %d", w.Code)
	}
}

// TestServerMux tests that routes are properly registered
func TestServerMux(t *testing.T) {
	s := NewServer(8094)
	defer s.Stop()

	routes := []string{
		"/api/v1/health",
		"/api/v1/status",
		"/api/v1/driver/start",
		"/api/v1/driver/stop",
		"/api/v1/driver/status",
		"/api/v1/pipeline/run",
		"/api/v1/pipeline/status",
		"/api/v1/asic/discover",
		"/api/v1/asic/probe",
		"/api/v1/asic/protocol",
		"/api/v1/asic/provision",
		"/api/v1/asic/troubleshoot",
		"/api/v1/asic/test",
		"/api/v1/asic/configure",
		"/api/v1/rules",
		"/api/v1/chat",
		"/api/v1/shutdown",
		"/api/v1/pipeline/logs",
	}

	for _, route := range routes {
		req := httptest.NewRequest(http.MethodGet, route, nil)
		w := httptest.NewRecorder()
		s.mux.ServeHTTP(w, req)

		// Should not get "404 page not found"
		if w.Code == 404 && w.Body.String() == "404 page not found\n" {
			t.Errorf("route %s not registered", route)
		}
	}
}

// TestPingEndpoint tests basic server responsiveness
func TestPingEndpoint(t *testing.T) {
	s := NewServer(8095)
	defer s.Stop()

	// Start server
	go func() {
		if err := s.Start(); err != nil {
			t.Errorf("failed to start server: %v", err)
		}
	}()

	// Give server time to start
	time.Sleep(100 * time.Millisecond)

	// Ping health endpoint
	resp, err := http.Get("http://localhost:8095/api/v1/health")
	if err != nil {
		t.Fatalf("failed to connect to server: %v", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		t.Errorf("expected status 200, got %d", resp.StatusCode)
	}

	s.Stop()
	time.Sleep(100 * time.Millisecond)
}

